const cmd = `$env:Path='C:\\Windows\\System32;'+$env:Path
$ua='Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/155.0.0.0 Safari/537.36'
foreach($n in @(25,50,99,100)){
  $u="https://arctic-shift.photon-reddit.com/api/posts/search?subreddit=college&query=tutor&limit=$n"
  $code = curl.exe -s -o "$env:TEMP\\a3.json" -w "%{http_code} %{size_download}" -x http://127.0.0.1:7897 -H "User-Agent: $ua" --max-time 40 --compressed $u
  Write-Output "limit=$n -> $code"
  if($code -like "4*"){ Get-Content "$env:TEMP\\a3.json" -Raw }
}
`;
const r = await tools.pwsh({ description: "Find ArcticShift max limit", command: cmd, timeoutMs: 180000 });
console.log(r.kind === 'foreground' ? r.stdout.text + "|ERR:" + r.stderr.text : JSON.stringify(r));
